-- Bounded G9 future CHECK/ACTIVATE. Import/source/cleanup protocols are unchanged.
-- Approval is exact DATA from reviewed Actions; SQL independently proves the
-- same source/native/calendar/prices and intended transition under write locks.
create schema private_fcf_future_activation;
revoke all on schema private_fcf_future_activation from public,anon,authenticated,service_role;

create function private_fcf_future_activation.official_clock(p_round int)returns timestamptz language plpgsql security definer set search_path=public,pg_temp as $$declare f record;wall timestamp;utc timestamptz;earliest timestamptz;begin
 for f in select e.f from pg_temp._fcf_expected e where e.rn=p_round loop
  perform private_fcf_six_target_release.require(f.f->>'time'~'^([01][0-9]|2[0-3]):[0-5][0-9]$','official Madrid kickoff required');
  wall:=(f.f->>'date')::date+(f.f->>'time')::time;utc:=wall at time zone'Europe/Madrid';
  perform private_fcf_six_target_release.require(utc at time zone'Europe/Madrid'=wall and(utc-interval'1 hour')at time zone'Europe/Madrid'<>wall and(utc+interval'1 hour')at time zone'Europe/Madrid'<>wall,'ambiguous/nonexistent Madrid kickoff');
  earliest:=least(earliest,utc);
 end loop;
 perform private_fcf_six_target_release.require(earliest is not null,'complete official round clock');return earliest;
end$$;
create function private_fcf_future_activation.next_round(p_after int,p_now timestamptz)returns int language plpgsql security definer set search_path=public,pg_temp as $$declare candidate int;begin
 for candidate in p_after+1..30 loop
  if exists(select 1 from pg_temp._fcf_expected e where e.rn=candidate and(e.f->>'statisticsStatus'<>'pending'or(e.f->>'date')::date<=(p_now at time zone'UTC')::date))or exists(select 1 from rounds r where r.competition_id=797 and r.season='2026/27'and r.number=candidate and r.deadline_at<=p_now)then continue;end if;
  if private_fcf_future_activation.official_clock(candidate)-interval'6 hours'>p_now then return candidate;end if;
 end loop;
 raise exception 'FCF_TARGET: no remaining future pending round';
end$$;
create function private_fcf_future_activation.after_image()returns jsonb language sql stable security definer set search_path=public,pg_temp as $$
 select jsonb_build_object('footballSha256',private_historical_statistics.state_sha256(797),'active',(select active from competitions where id=797),'pricingSnapshotText',private_fcf_six_target_release.pricing_snapshot(797)::text,'installedPolicy',(select to_jsonb(i)from private_historical_statistics.installed_policies i where competition_id=797),'markers',public.get_installed_historical_statistics_markers(797),'clubBindings',(select jsonb_agg(to_jsonb(b)order by club_id,category_id)from private_fcf_six_target_release.club_bindings b where competition_id=797),'cleanupSha256',(select encode(sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')from private_fcf_future_history.cleanup_receipt r where singleton));
$$;

create function public.fcf_future_current_target_check(p_activation_text text,p_sha256 text,p_activate boolean default false)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
#variable_conflict use_column
declare
 a jsonb;v jsonb;packet jsonb;mp jsonb;c competitions%rowtype;rec private_fcf_future_target_release.receipts%rowtype;
 projection jsonb;native jsonb;proposal jsonb;readiness jsonb;privacy_keys text[];now_utc timestamptz:=clock_timestamp();
 gap int;later_count int;last_played int;selected int;rid bigint;earliest timestamptz;deadline timestamptz;opening date;
 launch_projection jsonb;expected_proposal jsonb;projection_sha text;price_text text;prices jsonb;cost numeric;result jsonb;
 protected_players jsonb;protected_policy jsonb;protected_cleanup text;expected_competition jsonb;expected_rounds jsonb;after_native jsonb;after_image jsonb;
begin
 perform set_config('lock_timeout','10s',true);
 perform private_fcf_six_target_release.require(p_activate is not null and p_sha256~'^[a-f0-9]{64}$'and octet_length(p_activation_text)<=8388608 and encode(sha256(convert_to(p_activation_text,'UTF8')),'hex')=p_sha256,'exact bounded activation TEXT/SHA');a:=p_activation_text::jsonb;
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(a,array['schemaVersion','kind','targetSlug','sourceCommit','execution','importReceiptId','importRolloutText','importRolloutSha256','nativeSnapshotText','nativeSnapshotSha256','launchProposal','readiness','auditedUTC'])and a->'schemaVersion'='4'::jsonb and not exists(select 1 from unnest(array['targetSlug','sourceCommit','importReceiptId','importRolloutText','importRolloutSha256','nativeSnapshotText','nativeSnapshotSha256','auditedUTC'])field where jsonb_typeof(a->field)is distinct from'string')and a->>'kind'='fcf-future-current-target-activation'and a->>'targetSlug'='es-ct-tercera-g9'and a->>'sourceCommit'~'^[a-f0-9]{40}$'and jsonb_typeof(a->'importReceiptId')='string'and a->>'importReceiptId'~'^[1-9][0-9]*$','closed future activation schema4/G9');
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(a->'execution',array['repository','ref','commit','runId','runAttempt'])and a#>>'{execution,repository}'='Lovro-splichal-orhanizagi/mnzgorenjska'and a#>>'{execution,ref}'='refs/heads/main'and a#>>'{execution,commit}'=a->>'sourceCommit'and jsonb_typeof(a#>'{execution,runId}')='string'and a#>'{execution,runAttempt}'='"1"'::jsonb and a#>>'{execution,runId}'~'^[1-9][0-9]*$'and a#>>'{execution,runAttempt}'='1','exact approved main activation attempt1');
 perform private_fcf_six_target_release.lock_target(797);perform private_fcf_future_import.lock_dependencies();
 select *into c from competitions where id=797;select *into rec from private_fcf_future_target_release.receipts where competition_id=797 and id::text=a->>'importReceiptId';
 perform private_fcf_six_target_release.require(rec.id is not null and rec.rollout_text=a->>'importRolloutText'and rec.rollout_sha256=a->>'importRolloutSha256'and encode(sha256(convert_to(rec.rollout_text,'UTF8')),'hex')=rec.rollout_sha256,'exact committed original import receipt/rollout');
 v:=rec.rollout_text::jsonb;packet:=rec.packet_text::jsonb;
 perform private_fcf_six_target_release.require(rec.inventory_key=encode(sha256(convert_to((v->'inventoryBinding')::text,'UTF8')),'hex')and v->>'targetPacketText'=rec.packet_text and v->>'targetPacketSha256'=rec.packet_sha256 and encode(sha256(convert_to(rec.packet_text,'UTF8')),'hex')=rec.packet_sha256 and rec.source_fingerprint=v#>>'{inventoryBinding,sourceFingerprintSha256}'and rec.cleanup_before_sha256=v#>>'{cleanupBinding,beforeSha256}','original import packet/source/cleanup receipt identity');
 -- Committed retries are exact readback only. They do not call inactive-only
 -- projection/validation helpers, reselect an opening or claim fresh readiness.
 if rec.stage='activated'then
  perform private_fcf_six_target_release.require(c.active and rec.activation_result->>'activationText'=p_activation_text and rec.activation_result->>'activationSha256'=p_sha256 and rec.activation_result->'afterImage'=private_fcf_future_activation.after_image(),'saved activation/current afterimage drift');
  perform private_fcf_future_import.markers();perform private_fcf_six_target_release.no_target_users(797);
  return rec.activation_result->'result'||jsonb_build_object('noOp',true,'readbackOnly',true);
 end if;
 perform private_fcf_six_target_release.require(rec.stage='imported'and rec.activation_result is null and not c.active and c.prvi_fantasy_krog=1 and(a->>'auditedUTC')::timestamptz between now_utc-interval'24 hours'and now_utc,'inactive imported seed1/current activation audit');
 -- The saved import uses its ORIGINAL writer execution and pre-import packet;
 -- intentional post-import repricing does not need the old imported-state hash.
 v:=private_fcf_future_import.validate(rec.rollout_text,rec.rollout_sha256);
 perform private_fcf_six_target_release.no_target_users(797);perform private_fcf_six_target_release.privacy(797);perform private_fcf_six_target_release.compare_canonical(797);
 select coalesce(array_agg(distinct k order by k),'{}')into privacy_keys from(select public.anonimizacijski_kljuc(c.country_id||'|reg|'||e.reg)k from pg_temp._fcf_apps e union select public.anonimizacijski_kljuc(c.country_id||'|'||(e.x->>'ime'))from pg_temp._fcf_apps e)s;
 projection:=private_fcf_future_projection.capture(c.slug,privacy_keys);native:=projection->'native';proposal:=a->'launchProposal';readiness:=a->'readiness';
 perform private_fcf_six_target_release.require(a->>'nativeSnapshotText'=projection->>'dependencySnapshotText'and a->>'nativeSnapshotSha256'=projection->>'dependencySnapshotSha256'and encode(sha256(convert_to(a->>'nativeSnapshotText','UTF8')),'hex')=a->>'nativeSnapshotSha256'and native#>>'{dependencies,complete}'='true'and native#>>'{dependencies,competitionUserRows}'='0','exact locked SQL native/dependency snapshot');
 mp:=(v#>>'{identityPlan,mappingText}')::jsonb;
 perform private_fcf_six_target_release.require(not exists(select 1 from jsonb_array_elements(mp->'fixtures')m where not private_fcf_future_import.keys(m,array['sourceMatchId','sourceRound','matchId','roundId','homeTeamId','awayTeamId']))and not exists(with actual as(select jsonb_build_object('sourceMatchId',id,'sourceRound',rn,'matchId',mid,'roundId',rid,'homeTeamId',home,'awayTeamId',away)j from pg_temp._fcf_expected),expected as(select value j from jsonb_array_elements(mp->'fixtures'))(select *from actual except all select *from expected)union all(select *from expected except all select *from actual)),'complete original source/native mapping identities');
 perform private_fcf_six_target_release.require(not exists(select 1 from rounds where competition_id=797 and(deadline_at is null or played_on is null or played_on<'2026-07-01'or played_on>='2027-07-01')),'complete current native round dates/deadlines');
 perform private_fcf_six_target_release.require(not exists(select 1 from pg_temp._fcf_expected e where(e.f->>'date')::date<'2026-07-01'or(e.f->>'date')::date>='2027-07-01'),'exact current-season source dates');
 gap:=private_fcf_future_activation.next_round(0,now_utc);
 select count(distinct rn)into later_count from pg_temp._fcf_expected where f->>'statisticsStatus'='available'and rn>gap;
 select coalesce(max(rn),0)into last_played from pg_temp._fcf_expected where f->>'statisticsStatus'='available'and(rn<gap or later_count>2);
 selected:=case when gap>last_played then gap else private_fcf_future_activation.next_round(last_played,now_utc)end;
 select id into rid from rounds where competition_id=797 and season='2026/27'and number=selected;
 earliest:=private_fcf_future_activation.official_clock(selected);deadline:=earliest-interval'6 hours';select min((f->>'date')::date)into opening from pg_temp._fcf_expected where rn=selected;
 perform private_fcf_six_target_release.require((select count(*)from pg_temp._fcf_expected where rn=selected)=8 and not exists(select 1 from pg_temp._fcf_expected e join matches m on m.id=e.mid where e.rn=selected and(e.f->>'statisticsStatus'<>'pending'or(e.f->>'date')::date<=(now_utc at time zone'UTC')::date or m.played_on is distinct from(e.f->>'date')::date or m.imported_at is not null or m.kontumacija or m.vir_brez_izida or m.statistics_status<>'available'))and exists(select 1 from rounds where id=rid and played_on=opening and deadline_at>now_utc and lineups_locked_at is null)and deadline>clock_timestamp(),'same genuinely future untouched source/native opening');
 perform private_fcf_six_target_release.require(not exists(select 1 from jsonb_array_elements(native#>'{dependencies,rounds}')d where(d->>'roundId')::bigint=rid and(d->>'lineupRows'<>'0'or d->>'rosterRows'<>'0'or d->>'transferRows'<>'0'or d->>'chipRows'<>'0'or d->>'userRows'<>'0'))and not exists(select 1 from jsonb_array_elements(native#>'{dependencies,matches}')d where(d->>'matchId')::bigint in(select mid from pg_temp._fcf_expected where rn=selected)and(d->>'appearances'<>'0'or d->>'goals'<>'0'or d->>'userRows'<>'0')),'zero selected native statistics/user dependencies');
 launch_projection:=jsonb_build_object('targetSlug',c.slug,'competitionId',797,'sourceCode','4118349-4118588','season','2026/27','sourceFingerprintSha256',rec.source_fingerprint,'writerCommit',a->>'sourceCommit','fixtures',(select jsonb_agg(f order by id)from pg_temp._fcf_expected),'mapping',(select jsonb_agg(m order by m->>'sourceMatchId')from jsonb_array_elements(mp->'fixtures')m),'native',native);
 projection_sha:=encode(sha256(convert_to(private_fcf_future_import.canonical_json(launch_projection),'UTF8')),'hex');
 expected_proposal:=jsonb_build_object('schemaVersion',1,'kind','fcf-future-launch-proposal','targetSlug',c.slug,'competitionId',797,'season','2026/27','sourceCode','4118349-4118588','sourceFingerprintSha256',rec.source_fingerprint,'writerCommit',a->>'sourceCommit','projectionSha256',projection_sha,'roundNumber',selected,'roundId',rid,'firstFantasyPlayedOn',opening,'timeZone','Europe/Madrid','earliestKickoffUTC',to_char(earliest at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'deadlineUTC',to_char(deadline at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'fixtureIds',(select jsonb_agg(id order by id)from pg_temp._fcf_expected where rn=selected),'matchIds',(select jsonb_agg(mid order by mid)from pg_temp._fcf_expected where rn=selected));
 perform private_fcf_six_target_release.require(proposal=expected_proposal,'same frozen future proposal/projection; never replace an expired choice');
 perform private_fcf_six_target_release.require(private_fcf_future_import.keys(readiness,array['modelSha256','pricingSnapshotText','pricingSnapshotSha256','priceVector','squad','cheapestLegal15','launchProposal'])and jsonb_typeof(readiness->'pricingSnapshotText')='string'and jsonb_typeof(readiness->'pricingSnapshotSha256')='string'and jsonb_typeof(readiness->'modelSha256')='string'and readiness->'launchProposal'=proposal and readiness->>'modelSha256'~'^[a-f0-9]{64}$','closed same-proposal readiness/model identity');
 price_text:=projection#>>'{pricingSnapshot,snapshotText}';
 perform private_fcf_six_target_release.require(readiness->>'pricingSnapshotText'=price_text and readiness->>'pricingSnapshotSha256'=projection#>>'{pricingSnapshot,snapshotSha256}'and encode(sha256(convert_to(price_text,'UTF8')),'hex')=readiness->>'pricingSnapshotSha256','exact persisted pricing dependency TEXT/SHA');
 perform private_fcf_six_target_release.require(not exists(with actual as(select jsonb_build_object('id',id,'value',value,'value_start',value_start,'position',position,'position_source',position_source)j from players where competition_id=797),expected as(select value j from jsonb_array_elements(readiness->'priceVector'))(select *from actual except all select *from expected)union all(select *from expected except all select *from actual)),'actual full persisted price/provenance vector');
 perform private_fcf_six_target_release.require((select count(*)from private_fcf_six_target_release.club_bindings where competition_id=797)=16 and not exists(select 1 from pg_temp._fcf_clubs n left join private_fcf_six_target_release.club_bindings b on b.competition_id=797 and b.club_id=n.club and b.category_id=n.category and b.team_id=n.team and b.country_id=c.country_id and b.source_fingerprint=rec.source_fingerprint where b.team_id is null)and not exists(select 1 from players where competition_id=797 and active and team_id not in(select team from pg_temp._fcf_clubs))and not exists(select 1 from pg_temp._fcf_clubs n where not exists(select 1 from pg_temp._fcf_apps e join players p on p.competition_id=797 and p.reg_st=e.reg where e.team=n.team and p.team_id=n.team and p.active and p.position='GK'and p.position_source='zapisnik'and(e.x->>'vratar')::boolean and(e.x->>'zacetnik')::boolean)),'actual sixteen clubs/active explicit official keeper coverage');
 perform private_fcf_six_target_release.require(not exists(select 1 from players where competition_id=797 and(value is null or value<=0 or value::text in('NaN','Infinity','-Infinity')or value_start::text in('NaN','Infinity','-Infinity'))),'finite complete persisted price vector');
 prices:=public.stanje_lige(797);cost:=public.najcenejsi_kader(prices->'igralci');
 perform private_fcf_six_target_release.require((prices->>'klubov')::int=16 and cost is not null and cost<=100 and(readiness->>'cheapestLegal15')::numeric=cost and(prices->>'najvisja_cena')::numeric>=8 and coalesce((prices->>'privzetih')::numeric/nullif((prices->>'aktivnih')::numeric,0),1)<=0.7 and(prices->>'golov_brez_nastopa')::int=0,'actual varied prices and affordable legal15');
 perform private_fcf_six_target_release.require(jsonb_array_length(readiness->'squad')=15 and(select count(distinct(x->>'id')::bigint)from jsonb_array_elements(readiness->'squad')x)=15 and not exists(select 1 from jsonb_array_elements(readiness->'squad')x where not private_fcf_future_import.keys(x,array['id'])or not exists(select 1 from jsonb_array_elements(prices->'igralci')p where p->'id'=x->'id'))and(select sum((p->>'value')::numeric)from jsonb_array_elements(prices->'igralci')p where(p->>'id')::bigint in(select(x->>'id')::bigint from jsonb_array_elements(readiness->'squad')x))<=100,'unique actual affordable witness');
 perform private_fcf_six_target_release.require(not exists(select p->>'team_id'from jsonb_array_elements(prices->'igralci')p where(p->>'id')::bigint in(select(x->>'id')::bigint from jsonb_array_elements(readiness->'squad')x)group by p->>'team_id'having count(*)>3)and not exists(select q.position from(values('GK',2),('DEF',5),('MID',5),('FWD',3))q(position,n)where(select count(*)from jsonb_array_elements(prices->'igralci')p where p->>'position'=q.position and(p->>'id')::bigint in(select(x->>'id')::bigint from jsonb_array_elements(readiness->'squad')x))<>q.n),'legal15 actual quotas and club limit');
 result:=jsonb_build_object('stage',case when p_activate then 'activated'else 'checked'end,'targetSlug',c.slug,'receiptId',rec.id::text,'activationSha256',p_sha256,'targetPacketSha256',rec.packet_sha256,'sourceFingerprintSha256',rec.source_fingerprint,'firstFantasyRound',selected,'firstFantasyPlayedOn',opening,'deadlineAt',deadline,'active',p_activate,'cheapestLegal15',cost);
 if not p_activate then return result;end if;
 select jsonb_agg(to_jsonb(p)order by id)into protected_players from players p where competition_id=797;
 select to_jsonb(i)into protected_policy from private_historical_statistics.installed_policies i where competition_id=797;
 select encode(sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')into protected_cleanup from private_fcf_future_history.cleanup_receipt r where singleton;
 expected_competition:=(native->'competition')||jsonb_build_object('prvi_fantasy_krog',selected,'active',true);
 select jsonb_agg(case when(r->>'id')::bigint=rid then r||jsonb_build_object('played_on',opening,'deadline_at',deadline)else r end order by(r->>'id')::bigint)into expected_rounds from jsonb_array_elements(native->'rounds')r;
 perform private_fcf_six_target_release.require(deadline>clock_timestamp(),'approved official deadline expired before activation');
 update competitions set prvi_fantasy_krog=selected where id=797 and not active;
 update rounds set played_on=opening,deadline_at=deadline where id=rid and lineups_locked_at is null and deadline_at>clock_timestamp();perform private_fcf_six_target_release.require(found,'never reopen expired/locked selected round');
 update private_historical_statistics.installed_policies set first_fantasy_played_on=opening where competition_id=797;
 perform private_historical_statistics.authorize_release(797,packet#>>'{target,policyId}',packet#>>'{target,policySha256}',p_sha256);update competitions set active=true where id=797 and not active;
 select jsonb_build_object('competition',(select to_jsonb(co)from competitions co where id=797),'rounds',(select jsonb_agg(to_jsonb(r)order by id)from rounds r where competition_id=797),'matches',(select jsonb_agg(to_jsonb(m)order by m.id)from matches m join rounds r on r.id=m.round_id where r.competition_id=797))into after_native;
 perform private_fcf_six_target_release.require(after_native=jsonb_build_object('competition',expected_competition,'rounds',expected_rounds,'matches',native->'matches')and(select jsonb_agg(to_jsonb(p)order by id)from players p where competition_id=797)=protected_players and(select to_jsonb(i)from private_historical_statistics.installed_policies i where competition_id=797)=protected_policy||jsonb_build_object('first_fantasy_played_on',opening)and(select encode(sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex')from private_fcf_future_history.cleanup_receipt r where singleton)=protected_cleanup and deadline>clock_timestamp(),'same-TX exact intended opening/active afterimage and protected data');
 perform private_fcf_future_import.markers();perform private_fcf_six_target_release.compare_canonical(797);after_image:=private_fcf_future_activation.after_image();
 update private_fcf_future_target_release.receipts set stage='activated',activation_result=jsonb_build_object('activationText',p_activation_text,'activationSha256',p_sha256,'result',result,'afterImage',after_image)where id=rec.id;
 perform private_fcf_six_target_release.require(found and exists(select 1 from private_fcf_future_target_release.receipts where id=rec.id and stage='activated'and activation_result->>'activationSha256'=p_sha256 and activation_result->'afterImage'=private_fcf_future_activation.after_image()),'saved activation receipt/afterimage readback');return result;
end$$;
revoke all on all functions in schema private_fcf_future_activation from public,anon,authenticated,service_role;
revoke all on function public.fcf_future_current_target_check(text,text,boolean)from public,anon,authenticated;
grant execute on function public.fcf_future_current_target_check(text,text,boolean)to service_role;
